import re, sys
tex = open(sys.argv[1]).read()
tex = re.sub(r"(?m)%.*$", "", tex)
order = []
for m in re.finditer(r"\\cite\{([^}]*)\}", tex):
    for k in m.group(1).split(","):
        k = k.strip()
        if k not in order: order.append(k)
missing = [k for k in order if k not in REFS]
if missing: sys.exit(f"unknown keys {missing}")
with open("references.tex", "w") as f:
    f.write("\\begin{thebibliography}{%d}\n" % len(order))
    for k in order:
        doi, txt = REFS[k]
        f.write(f"\\bibitem{{{k}}} {txt}" + (f" \\url{{https://doi.org/{doi}}}." if doi else "") + "\n\n")
    f.write("\\end{thebibliography}\n")
print(len(order), "references; unused:", [k for k in REFS if k not in order])
